def refs():
    return [{**s, "subject": "math", "locator": "梯形兩底、兩腰、垂直高、等腰梯形底角與對角線、面積及判定", "observedPattern": "公開學校數學試題常以梯形的平行邊辨認、等腰條件、角度／對角線性質與面積計算考查圖形推理；本題只取能力方向。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]

